package escuela.personal.service;
import escuela.personal.dto.*;
import escuela.admin.dto.OpcionAutocompletado;
import escuela.common.exception.ReglaNegocioException;
import escuela.finanzas.dto.request.MovimientoManualRequest;
import escuela.finanzas.entity.DireccionMovimiento;
import escuela.finanzas.service.MovimientoManualService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.data.domain.*;
import org.springframework.security.access.AccessDeniedException;
import java.util.*;
import java.time.*;
import java.math.BigDecimal;

@Service @RequiredArgsConstructor @Transactional(readOnly=true)
public class PagoEmpleadoNominaService {
 private final PreparacionNominaService preparacion;
 private final EmpleadoService empleados;
 private final NamedParameterJdbcTemplate jdbc;
 private final MovimientoManualService movimientos;
 public record Fila(Long id,Long empleadoId,String codigo,String nombre,BigDecimal neto,String moneda,String estado,Long pagoId){}
 public record Resumen(long empleados,long pagados,BigDecimal total,BigDecimal pagado){public BigDecimal pendiente(){return total.subtract(pagado);}}
 public record Cuenta(Long id,String texto,BigDecimal saldo,Long version){}
 public record Vista(Fila fila,Cuenta cuenta,String motivoFinanciero,BigDecimal saldoPosterior,String sello){}
 public record Intento(Long id,String estado,BigDecimal monto,String moneda,Long movimientoId,String referencia,String motivo,String fecha,String usuario,Long reversaMovimiento,String referenciaReversa,String motivoReversa,String fechaReversa,String usuarioReversa){
  public String estadoTexto(){return switch(estado){case "REVERTIDO"->"Pago cancelado";case "PAGADO"->"Pagado";case "RECHAZADO"->"Rechazado";default->estado;};}
 }
 public record Cuota(Long id,String concepto,BigDecimal importe,BigDecimal saldo,String moneda){}
 public record CuentaCancelacion(String texto,BigDecimal importe){}
 public List<CuentaCancelacion> cuentasCancelar(Long id){
  financiero(true);preparacion.obtener(id);
  return jdbc.query("SELECT coalesce(f.cuenta_texto,c.codigo||' · '||c.nombre) cuenta,sum(coalesce(f.importe,ni.monto)) importe FROM nomina_pago_intento ni JOIN nomina_fila_efectiva ne ON ne.id=ni.fila_id JOIN movimiento_financiero m ON m.id=ni.movimiento_id LEFT JOIN nomina_pago_fuente f ON f.pago_id=ni.id JOIN cuenta_financiera c ON c.id=coalesce(f.cuenta_id,m.cuenta_id) WHERE ne.borrador_id=:id AND ni.institucion_id=:inst AND ni.estado='PAGADO' GROUP BY coalesce(f.cuenta_texto,c.codigo||' · '||c.nombre) ORDER BY 1",p(false).addValue("id",id),(r,n)->new CuentaCancelacion(r.getString("cuenta"),r.getBigDecimal("importe")));
 }
 @Transactional public void cancelarTodos(Long id,PagoEmpleadoNominaForm f){
  financiero(true);if(!f.isConfirmado())throw regla("Confirma que se recuperó todo el dinero en sus cuentas originales.");
  jdbc.queryForObject("SELECT id FROM nomina_borrador WHERE id=:id AND institucion_id=:inst FOR UPDATE",p(true).addValue("id",id),Long.class);
  if(!Objects.equals(preparacion.obtener(id).version(),f.getVersion()))throw regla("La nómina cambió; revisa nuevamente antes de cancelar sus pagos.");
  var filas=new ArrayList<Fila>();int pagina=0;Page<Fila> page;do{page=listar(id,"","PAGADO",pagina++,100);filas.addAll(page.getContent());}while(page.hasNext());
  if(filas.isEmpty())throw regla("No hay pagos vigentes para cancelar; no se realizó otra operación.");
  // Cualquier fallo revierte también las compensaciones anteriores de este lote.
  for(var fila:filas){f.setVersion(preparacion.obtener(id).version());revertir(id,fila.id(),fila.pagoId(),f);}
 }
 private MapSqlParameterSource p(boolean escribir){var a=empleados.autorizarSalarios(escribir);return new MapSqlParameterSource("inst",a.institucionId()).addValue("actor",a.usuarioId());}
 public boolean puedePagar(){return empleados.permitido("CONDICION_SALARIAL_ADMINISTRAR")&&empleados.permitido("MOVIMIENTO_FINANCIERO_REGISTRAR");}
 public boolean puedeRevertir(){return puedePagar()&&empleados.permitido("MOVIMIENTO_FINANCIERO_REVERTIR");}
 private void financiero(boolean reversa){p(true);if(!(reversa?puedeRevertir():puedePagar()))throw new AccessDeniedException("Se requieren permisos salariales y financieros para esta operación");}
 public boolean autorizada(Long id){preparacion.obtener(id);return jdbc.queryForObject("SELECT count(*) FROM nomina_autorizacion WHERE borrador_id=:id AND institucion_id=:inst",p(false).addValue("id",id),Long.class)>0;}
 private static final String FILAS=" FROM nomina_fila_efectiva ne JOIN nomina_borrador b ON b.id=ne.borrador_id LEFT JOIN nomina_pago_intento ni ON ni.fila_id=ne.id AND ni.estado='PAGADO' WHERE ne.borrador_id=:id AND ne.institucion_id=:inst AND ne.revision=b.revision_actual ";
 private static final String SELECT="SELECT ne.id,ne.empleado_id,ne.empleado_codigo,ne.empleado_nombre,ne.propuesto,ne.moneda,CASE WHEN ne.tratamiento='NO_APLICAR' THEN 'NO_APLICAR' WHEN ni.id IS NOT NULL THEN 'PAGADO' WHEN ne.tratamiento='POSPONER' THEN 'POSPUESTO' ELSE 'PENDIENTE' END estado,ni.id pago_id";
 private org.springframework.jdbc.core.RowMapper<Fila> map(){return (r,n)->new Fila(r.getLong("id"),r.getLong("empleado_id"),r.getString("empleado_codigo"),r.getString("empleado_nombre"),r.getBigDecimal("propuesto"),r.getString("moneda"),r.getString("estado"),r.getObject("pago_id",Long.class));}
 public Fila fila(Long id,Long fila){preparacion.obtener(id);return jdbc.query(SELECT+FILAS+" AND ne.id=:fila",p(false).addValue("id",id).addValue("fila",fila),map()).stream().findFirst().orElseThrow(()->new AccessDeniedException("Empleado de esta nómina no autorizado"));}
 public Page<Fila> listar(Long id,String q,String estado,int pagina,int tamanio){return listar(id,q,estado,pagina,tamanio,null);}
 public Page<Fila> listar(Long id,String q,String estado,int pagina,int tamanio,Long empleadoId){preparacion.obtener(id);String filtro=" AND (CAST(:empleado AS bigint) IS NULL OR ne.empleado_id=:empleado) AND strpos(lower(ne.empleado_codigo||' '||ne.empleado_nombre),lower(:q))>0 AND (:estado='TODOS' OR :estado=CASE WHEN ne.tratamiento='NO_APLICAR' THEN 'NO_APLICAR' WHEN ni.id IS NOT NULL THEN 'PAGADO' WHEN ne.tratamiento='POSPONER' THEN 'POSPUESTO' ELSE 'PENDIENTE' END)";String est=Set.of("PENDIENTE","PAGADO","POSPUESTO","NO_APLICAR").contains(Objects.toString(estado,""))?estado:"TODOS";var pg=PageRequest.of(Math.max(0,pagina),Set.of(10,25,50,100).contains(tamanio)?tamanio:25);var par=p(false).addValue("id",id).addValue("empleado",empleadoId).addValue("q",OrganizacionLaboralService.texto(q,200)).addValue("estado",est);long n=jdbc.queryForObject("SELECT count(*)"+FILAS+filtro,par,Long.class);return new PageImpl<>(jdbc.query(SELECT+FILAS+filtro+" ORDER BY ne.id LIMIT :limite OFFSET :offset",par.addValue("limite",pg.getPageSize()).addValue("offset",pg.getOffset()),map()),pg,n);}
 public List<OpcionAutocompletado> buscarEmpleados(Long id,String q){
  preparacion.obtener(id);var texto=OrganizacionLaboralService.texto(q,200);if(!texto.isBlank()&&texto.length()<3)return List.of();
  return jdbc.query("SELECT ne.empleado_id,ne.empleado_codigo,ne.empleado_nombre"+FILAS+" AND strpos(lower(ne.empleado_codigo||' '||ne.empleado_nombre),lower(:q))>0 ORDER BY lower(ne.empleado_nombre),ne.empleado_id LIMIT 11",p(false).addValue("id",id).addValue("q",texto),(r,n)->new OpcionAutocompletado(r.getLong("empleado_id"),r.getString("empleado_codigo")+" · "+r.getString("empleado_nombre"),"Empleado incluido en esta revisión"));
 }
 public Resumen resumen(Long id){preparacion.obtener(id);return jdbc.queryForObject("SELECT count(*) FILTER(WHERE ne.tratamiento<>'NO_APLICAR') n,count(ni.id) pagados,coalesce(sum(ne.propuesto),0) total,coalesce(sum(ne.propuesto) FILTER(WHERE ni.id IS NOT NULL),0) pagado"+FILAS,p(false).addValue("id",id),(r,n)->new Resumen(r.getLong("n"),r.getLong("pagados"),r.getBigDecimal("total"),r.getBigDecimal("pagado")));}
 @Transactional public void autorizar(Long id,Long version,String motivo){p(true);texto(motivo,2000,"motivo de autorización");var b=preparacion.bloquearParaAplicar(id,version);if(jdbc.queryForObject("SELECT count(*) FROM nomina_fila_efectiva WHERE borrador_id=:id AND revision=:rev AND tratamiento<>'NO_APLICAR' AND propuesto<=0",p(true).addValue("id",id).addValue("rev",b.revision()),Long.class)>0)throw regla("Hay importes netos de cero; requieren resolver la configuración antes de autorizar. No se generan egresos de cero.");
  var par=p(true).addValue("id",id).addValue("rev",b.revision()).addValue("periodo",b.periodoId()).addValue("motivo",motivo.strip());jdbc.update("INSERT INTO nomina_autorizacion(borrador_id,institucion_id,periodo_id,revision,usuario_id,motivo) VALUES(:id,:inst,:periodo,:rev,:actor,:motivo)",par);jdbc.update("UPDATE nomina_borrador SET estado=nomina_estado_vigente(:id),motivo_operacion=:motivo,actualizado_por_id=:actor,actualizado_en=CURRENT_TIMESTAMP,version=version+1 WHERE id=:id AND institucion_id=:inst",par);
 }
 private void bloqueos(Long id,Long fila){var r=fila(id,fila);var par=p(true).addValue("id",id).addValue("emp",r.empleadoId());jdbc.queryForObject("SELECT id FROM nomina_borrador WHERE id=:id AND institucion_id=:inst FOR UPDATE",par,Long.class);jdbc.queryForObject("SELECT id FROM empleado WHERE id=:emp AND institucion_id=:inst FOR UPDATE",par,Long.class);if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT activo FROM institucion WHERE id=:inst FOR SHARE",par,Boolean.class)))throw regla("La institución está inactiva; sólo consulta.");jdbc.query("SELECT id FROM prestamo_empleado WHERE empleado_id=:emp AND institucion_id=:inst ORDER BY id FOR UPDATE",par,(org.springframework.jdbc.core.RowCallbackHandler)rset->{});}
 private void pendiente(Long id,Long fila,Long version){var b=preparacion.obtener(id);if(!autorizada(id)||!Set.of("AUTORIZADA","PARCIALMENTE_PAGADA","PAGADA").contains(b.estado()))throw regla("Autoriza primero la nómina. Las aplicadas antiguas no se convierten en pagos individuales.");if(!Objects.equals(b.version(),version))throw regla("La nómina cambió; vuelve a revisar el empleado antes de confirmar.");if(fila(id,fila).estado().equals("NO_APLICAR"))throw regla("Este empleado fue excluido de este periodo con justificación; no puede pagarse desde esta revisión.");if(fila(id,fila).pagoId()!=null)throw regla("El empleado ya tiene un pago vigente. No se registró otro egreso.");}
 public List<Cuota> cuotas(Long id,Long fila){fila(id,fila);return jdbc.query("SELECT (x->>'id')::bigint id,(x->>'concepto_codigo')||' · '||(x->>'concepto_nombre') concepto,(x->>'cuota')::numeric importe,s.saldo,p.moneda FROM nomina_fila_efectiva ne CROSS JOIN LATERAL jsonb_array_elements(ne.fuentes->'prestamos') x JOIN prestamo_empleado p ON p.id=(x->>'id')::bigint AND p.empleado_id=ne.empleado_id AND p.institucion_id=ne.institucion_id JOIN prestamo_saldo s ON s.id=p.id WHERE ne.borrador_id=:id AND ne.id=:fila AND ne.institucion_id=:inst ORDER BY p.id",p(false).addValue("id",id).addValue("fila",fila),(r,n)->new Cuota(r.getLong("id"),r.getString("concepto"),r.getBigDecimal("importe"),r.getBigDecimal("saldo"),r.getString("moneda")));}
 private Cuenta cuenta(Long cuenta,String moneda,boolean lock){var par=p(true).addValue("cuenta",cuenta).addValue("moneda",moneda);if(lock)jdbc.query("SELECT id FROM cuenta_financiera WHERE id=:cuenta AND institucion_id=:inst FOR UPDATE",par,(r,n)->r.getLong(1));return jdbc.query("SELECT c.id,c.codigo||' · '||c.nombre texto,c.version,coalesce((SELECT m.saldo_posterior FROM movimiento_financiero m WHERE m.cuenta_id=c.id ORDER BY m.secuencia_cuenta DESC LIMIT 1),c.saldo_inicial) saldo FROM cuenta_financiera c WHERE c.id=:cuenta AND c.institucion_id=:inst AND c.activo AND c.tipo IN ('CAJA','BANCO') AND c.moneda=:moneda",par,(r,n)->new Cuenta(r.getLong("id"),r.getString("texto"),r.getBigDecimal("saldo"),r.getLong("version"))).stream().findFirst().orElseThrow(()->regla("Selecciona caja o banco institucional activo y de la moneda de la nómina."));}
 private Map<String,Object> motivo(Long id,boolean reversa,boolean lock){var par=p(true).addValue("mot",id);return jdbc.queryForList("SELECT id,codigo,nombre,version FROM motivo_financiero WHERE id=:mot AND institucion_id=:inst AND activo AND naturaleza IN (:dir,'AMBOS')"+(lock?" FOR SHARE":""),par.addValue("dir",reversa?"INGRESO":"EGRESO")).stream().findFirst().orElseThrow(()->regla("Selecciona un motivo financiero activo compatible con "+(reversa?"ingreso por devolución.":"egreso de nómina.")));}
 private void captura(PagoEmpleadoNominaForm f){texto(f.getReferencia(),150,"referencia");texto(f.getMotivo(),2000,"motivo");if(f.getSolicitud()==null||f.getVersion()==null)throw regla("Recarga el formulario antes de confirmar.");}
 public Vista revisar(Long id,Long fila,PagoEmpleadoNominaForm f){financiero(false);captura(f);pendiente(id,fila,f.getVersion());var r=fila(id,fila);var c=cuenta(f.getCuentaId(),r.moneda(),false);var m=motivo(f.getMotivoPagoId(),false,false);if(c.saldo().compareTo(r.neto())<0)throw regla("Saldo insuficiente para el pago completo de este empleado.");for(var cuota:cuotas(id,fila))if(cuota.importe().compareTo(cuota.saldo())>0||!cuota.moneda().equals(r.moneda()))throw regla("El saldo del préstamo no admite esta cuota autorizada. Revisa el caso sin cambiar el importe histórico.");String sello=PreparacionNominaService.sello(id+"|"+f.getVersion()+"|"+r+"|"+c+"|"+m+"|"+f.getSolicitud()+"|"+f.getReferencia().strip()+"|"+f.getMotivo().strip()+"|"+cuotas(id,fila));return new Vista(r,c,m.get("codigo")+" · "+m.get("nombre"),c.saldo().subtract(r.neto()),sello);}
 @Transactional public Long pagar(Long id,Long fila,PagoEmpleadoNominaForm f,String sello){financiero(false);if(!f.isConfirmado())throw regla("Confirma la salida real de dinero para este empleado.");bloqueos(id,fila);var r=fila(id,fila);cuenta(f.getCuentaId(),r.moneda(),true);motivo(f.getMotivoPagoId(),false,true);var v=revisar(id,fila,f);if(!Objects.equals(v.sello(),sello))throw regla("Cambió la cuenta, saldo o captura. Revisa nuevamente; no se movió dinero.");var par=p(true).addValue("solicitud",f.getSolicitud());if(jdbc.queryForObject("SELECT count(*) FROM nomina_pago_intento WHERE institucion_id=:inst AND solicitud=:solicitud",par,Long.class)>0)throw regla("Este intento ya se registró. No se repitió el pago.");Long pago=jdbc.queryForObject("SELECT nextval(pg_get_serial_sequence('nomina_pago_intento','id'))",par,Long.class);
  var mov=movimientos.registrarNominaEmpleado(new MovimientoManualRequest(empleados.autorizarSalarios(true).institucionId(),f.getCuentaId(),null,ahora(),DireccionMovimiento.EGRESO,f.getMotivoPagoId(),r.neto(),"Pago individual de nómina "+preparacion.obtener(id).folio(),"NPI-"+pago,"Personal de la institución","NOMINA-EMP:"+pago));
  registrar(id,fila,pago,"PAGADO",f,mov.id());for(var q:cuotas(id,fila)){jdbc.update("INSERT INTO prestamo_abono_nomina(pago_id,prestamo_id,importe,saldo_anterior,saldo_posterior) VALUES(:pago,:prestamo,:monto,:saldo,:saldo-:monto)",p(true).addValue("pago",pago).addValue("prestamo",q.id()).addValue("monto",q.importe()).addValue("saldo",q.saldo()));estadoPrestamo(q.id(),"Abono de nómina NPI-"+pago);}estadoNomina(id,"Pago individual NPI-"+pago);return pago;
 }
 private void registrar(Long id,Long fila,Long pago,String estado,PagoEmpleadoNominaForm f,Long movimiento){var r=fila(id,fila);jdbc.update("INSERT INTO nomina_pago_intento(id,fila_id,institucion_id,solicitud,estado,monto,moneda,movimiento_id,referencia,motivo,usuario_id) VALUES(:pago,:fila,:inst,:solicitud,:estado,:monto,:moneda,:mov,:ref,:motivo,:actor)",p(true).addValue("pago",pago).addValue("fila",fila).addValue("solicitud",f.getSolicitud()).addValue("estado",estado).addValue("monto",r.neto()).addValue("moneda",r.moneda()).addValue("mov",movimiento,java.sql.Types.BIGINT).addValue("ref",f.getReferencia().strip()).addValue("motivo",f.getMotivo().strip()));}
 @Transactional public void rechazar(Long id,Long fila,PagoEmpleadoNominaForm f){p(true);bloqueos(id,fila);captura(f);pendiente(id,fila,f.getVersion());Long intento=jdbc.queryForObject("SELECT nextval(pg_get_serial_sequence('nomina_pago_intento','id'))",p(true),Long.class);registrar(id,fila,intento,"RECHAZADO",f,null);estadoNomina(id,"Intento rechazado sin salida de dinero");}
 @Transactional public void revertir(Long id,Long fila,Long pago,PagoEmpleadoNominaForm f){financiero(true);if(!f.isConfirmado())throw regla("Confirma que los fondos de este pago realmente regresaron a la cuenta original. Un rechazo sin salida no es una reversa.");bloqueos(id,fila);captura(f);var r=fila(id,fila);if(!autorizada(id)||!Objects.equals(r.pagoId(),pago)||!Objects.equals(preparacion.obtener(id).version(),f.getVersion()))throw regla("El pago ya cambió o fue revertido. Recarga; no se publicó otra reversa.");var par=p(true).addValue("pago",pago);if(jdbc.queryForObject("SELECT count(*) FROM nomina_pago_fuente WHERE pago_id=:pago",par,Long.class)>0){devolverFuentes(id,pago,f);return;}Long original=jdbc.queryForObject("SELECT movimiento_id FROM nomina_pago_intento WHERE id=:pago AND fila_id=:fila AND estado='PAGADO'",par.addValue("fila",fila),Long.class);Long cuentaId=jdbc.queryForObject("SELECT cuenta_id FROM movimiento_financiero WHERE id=:mov",par.addValue("mov",original),Long.class);cuenta(cuentaId,r.moneda(),true);motivo(f.getMotivoPagoId(),true,true);
  var mov=movimientos.compensarNominaEmpleado(new MovimientoManualRequest(empleados.autorizarSalarios(true).institucionId(),cuentaId,null,ahora(),DireccionMovimiento.INGRESO,f.getMotivoPagoId(),r.neto(),"Devolución de pago individual NPI-"+pago,"NPI-"+pago,"Personal de la institución","NOMINA-REV:"+pago),original);
  Long rev=jdbc.queryForObject("INSERT INTO nomina_pago_reversa(pago_id,institucion_id,movimiento_id,referencia,motivo,usuario_id) VALUES(:pago,:inst,:mov,:ref,:motivo,:actor) RETURNING id",par.addValue("mov",mov.id()).addValue("ref",f.getReferencia().strip()).addValue("motivo",f.getMotivo().strip()),Long.class);jdbc.update("INSERT INTO prestamo_abono_compensacion(reversa_id,pago_id,prestamo_id,importe) SELECT :rev,pago_id,prestamo_id,importe FROM prestamo_abono_nomina WHERE pago_id=:pago",par.addValue("rev",rev));jdbc.update("UPDATE nomina_pago_intento SET estado='REVERTIDO' WHERE id=:pago AND institucion_id=:inst",par);jdbc.queryForList("SELECT prestamo_id FROM prestamo_abono_nomina WHERE pago_id=:pago ORDER BY prestamo_id",par,Long.class).forEach(prestamo->estadoPrestamo(prestamo,"Compensación de abono NPI-"+pago));estadoNomina(id,"Reversa individual NPI-"+pago+"; vuelve a pendiente sin afectar otros empleados");
 }
 private void devolverFuentes(Long id,Long pago,PagoEmpleadoNominaForm f){
  var par=p(true).addValue("pago",pago);var fuentes=jdbc.queryForList("SELECT * FROM nomina_pago_fuente WHERE pago_id=:pago ORDER BY cuenta_id,ordinal",par);
  for(var fuente:fuentes)cuenta(((Number)fuente.get("cuenta_id")).longValue(),fila(id,jdbc.queryForObject("SELECT fila_id FROM nomina_pago_intento WHERE id=:pago",par,Long.class)).moneda(),true);
  motivo(f.getMotivoPagoId(),true,true);Long primero=null;
  for(var fuente:fuentes){int ordinal=((Number)fuente.get("ordinal")).intValue();Long cuenta=((Number)fuente.get("cuenta_id")).longValue(),original=((Number)fuente.get("movimiento_id")).longValue();
   var mov=movimientos.compensarNominaEmpleado(new MovimientoManualRequest(empleados.autorizarSalarios(true).institucionId(),cuenta,null,ahora(),DireccionMovimiento.INGRESO,f.getMotivoPagoId(),(BigDecimal)fuente.get("importe"),"Cancelación del pago NPI-"+pago,"NPI-"+pago,"Personal de la institución","NOMINA-REV:"+pago+":"+ordinal),original);
   if(primero==null)primero=mov.id();jdbc.update("INSERT INTO nomina_pago_fuente_reversa(pago_id,ordinal,movimiento_id) VALUES(:pago,:ordinal,:mov)",p(true).addValue("pago",pago).addValue("ordinal",ordinal).addValue("mov",mov.id()));
  }
  jdbc.update("INSERT INTO nomina_pago_reversa(pago_id,institucion_id,movimiento_id,referencia,motivo,usuario_id) VALUES(:pago,:inst,:mov,:ref,:motivo,:actor)",par.addValue("mov",primero).addValue("ref",f.getReferencia().strip()).addValue("motivo",f.getMotivo().strip()));
  jdbc.update("UPDATE nomina_pago_intento SET estado='REVERTIDO' WHERE id=:pago AND institucion_id=:inst",par);estadoNomina(id,"Cancelación individual NPI-"+pago+"; fondos recuperados en sus cuentas originales");
 }
 private void estadoPrestamo(Long id,String motivo){jdbc.update("UPDATE prestamo_empleado SET estado=CASE WHEN (SELECT saldo FROM prestamo_saldo WHERE id=:id)=0 THEN 'LIQUIDADO' ELSE 'ACTIVO' END,motivo_operacion=:motivo,actualizado_por_id=:actor,actualizado_en=CURRENT_TIMESTAMP,version=version+1 WHERE id=:id AND institucion_id=:inst",p(true).addValue("id",id).addValue("motivo",motivo));}
 private void estadoNomina(Long id,String motivo){var t=resumen(id);String estado=jdbc.queryForObject("SELECT nomina_estado_vigente(:id)",p(true).addValue("id",id),String.class);jdbc.update("UPDATE nomina_borrador SET estado=:estado,motivo_operacion=:motivo,actualizado_por_id=:actor,actualizado_en=CURRENT_TIMESTAMP,version=version+1 WHERE id=:id AND institucion_id=:inst",p(true).addValue("id",id).addValue("estado",estado).addValue("motivo",motivo));}
 public Page<Intento> historial(Long id,Long fila,int pagina){fila(id,fila);var par=p(false).addValue("fila",fila);var pg=PageRequest.of(Math.max(0,pagina),20);long n=jdbc.queryForObject("SELECT count(*) FROM nomina_pago_intento WHERE fila_id=:fila AND institucion_id=:inst",par,Long.class);return new PageImpl<>(jdbc.query("SELECT ni.*,nr.movimiento_id mov_compensacion,nr.referencia ref_compensacion,nr.motivo mot_compensacion,ur.username actor_compensacion,to_char(nr.ocurrido_en AT TIME ZONE i.zona_horaria,'DD/MM/YYYY HH24:MI') fecha_compensacion,to_char(ni.ocurrido_en AT TIME ZONE i.zona_horaria,'DD/MM/YYYY HH24:MI') fecha,u.username FROM nomina_pago_intento ni JOIN institucion i ON i.id=ni.institucion_id JOIN usuario u ON u.id=ni.usuario_id LEFT JOIN nomina_pago_reversa nr ON nr.pago_id=ni.id LEFT JOIN usuario ur ON ur.id=nr.usuario_id WHERE ni.fila_id=:fila AND ni.institucion_id=:inst ORDER BY ni.id DESC LIMIT 20 OFFSET :offset",par.addValue("offset",pg.getOffset()),(r,k)->new Intento(r.getLong("id"),r.getString("estado"),r.getBigDecimal("monto"),r.getString("moneda"),r.getObject("movimiento_id",Long.class),r.getString("referencia"),r.getString("motivo"),r.getString("fecha"),r.getString("username"),r.getObject("mov_compensacion",Long.class),r.getString("ref_compensacion"),r.getString("mot_compensacion"),r.getString("fecha_compensacion"),r.getString("actor_compensacion"))),pg,n);}
 public List<OpcionAutocompletado> cuentas(Long id,String q){financiero(false);var b=preparacion.obtener(id);var t=OrganizacionLaboralService.texto(q,200);if(!t.isBlank()&&t.length()<3)return List.of();return jdbc.query("SELECT id,codigo,nombre,tipo FROM cuenta_financiera WHERE institucion_id=:inst AND activo AND tipo IN ('CAJA','BANCO') AND moneda=:moneda AND strpos(lower(codigo||' '||nombre),lower(:q))>0 ORDER BY id LIMIT 11",p(true).addValue("q",t).addValue("moneda",b.moneda()),(r,n)->new OpcionAutocompletado(r.getLong("id"),r.getString("codigo")+" · "+r.getString("nombre"),r.getString("tipo")));}
 public List<OpcionAutocompletado> motivos(Long id,String q,boolean reversa){financiero(reversa);preparacion.obtener(id);String t=OrganizacionLaboralService.texto(q,200);if(!t.isBlank()&&t.length()<3)return List.of();return jdbc.query("SELECT id,codigo,nombre FROM motivo_financiero WHERE institucion_id=:inst AND activo AND naturaleza IN (:dir,'AMBOS') AND strpos(lower(codigo||' '||nombre),lower(:q))>0 ORDER BY id LIMIT 11",p(true).addValue("q",t).addValue("dir",reversa?"INGRESO":"EGRESO"),(r,n)->new OpcionAutocompletado(r.getLong("id"),r.getString("codigo")+" · "+r.getString("nombre"),reversa?"Devolución de fondos":"Pago individual"));}
 private LocalDateTime ahora(){return LocalDateTime.now(ZoneId.of(jdbc.queryForObject("SELECT zona_horaria FROM institucion WHERE id=:inst",p(true),String.class))).withSecond(0).withNano(0);}
 private static void texto(String s,int max,String nombre){if(s==null||s.isBlank()||s.length()>max)throw regla("Captura "+nombre+" con máximo "+max+" caracteres.");}
 private static ReglaNegocioException regla(String s){return new ReglaNegocioException(s);}
}
